    "interviewAnswer": "저라면 우선 이 상황의 핵심을 가격 위험을 줄이려는 선구매가 설계·재고·자금 위험을 키울 수 있다는 점이라고 보겠습니다. 발주처가 일정을 요구한다고 해서 바로 인원이나 작업시간부터 늘리지는 않겠습니다. 먼저 확정 물량과 변경 가능 물량을 구분하고 무리한 전량 발주를 보류한다.\n\n그다음 원인을 확인하겠습니다. 잔여물량·납기·보관비·자금 일정·변경 가능성과 계약 가격조정 요건을 확인한다. 이 자료를 현황 공정표와 연결해 해당 작업이 주공정인지, 여유가 있는지, 후속 작업을 다른 구간에서 진행할 수 있는지 확인하겠습니다. 작업 자체의 지연과 준공일 영향을 구분하고, 추가 투입비뿐 아니라 대기비와 현장 유지비도 같은 비교기간으로 산정하겠습니다.\n\n대안으로는 확정분 분할 선구매 / 장기 공급조건 협의 / 대체 규격·공급원 등을 비교하겠습니다. 확정된 핵심 물량을 중심으로 분할 발주하고 장기 공급조건을 비교한다. 변경 가능 물량은 설계 확정일과 납기를 연결해 구매하며 가격조정은 계약 요건 확인 후 별도 추진한다. 각 안의 단축 가능성과 비용은 협력업체의 실제 자원, 자재 확보, 검측과 승인기간까지 확인해 제시하겠습니다. 비용이 낮아도 안전과 품질을 충족하지 못하는 안은 선택하지 않겠습니다. 반대로 비용이 높은 안도 준공 위험을 실질적으로 줄이는지 근거를 확인하겠습니다.\n\n실행을 위해서는 구매·공무·설계·감리와 규격 및 물량을 확정하고 발주처에는 가격 영향과 계약상 협의 필요사항을 근거로 제시한다. 저는 협의 때 확인된 사실, 아직 필요한 검토, 결정이 필요한 날짜를 구분해서 전달하겠습니다. 합의되지 않은 추가비나 공기 조정은 자동으로 인정받는다고 가정하지 않고, 계약상 절차와 객관적인 작업기록을 갖추겠습니다. 작업팀에는 변경된 순서와 책임, 중지·재개 조건을 분명히 공유하겠습니다.\n\n마지막으로 확정 물량 비율, 발주단가, 재고·보관상태, 현금 지급과 납기 준수율을 본다. 계획한 효과가 나오지 않거나 안전·품질 징후가 나빠지면 즉시 해당 작업을 통제하고 원인을 재분석하겠습니다. 실행 결과를 발주처와 공유하면서 대안을 조정하는 방식으로 관리하겠습니다.",
