    "interviewAnswer": "저라면 우선 이 상황의 핵심을 균열 원인이 진행 중인 하중·배수·지반 문제인지 확인해야 한다는 점이라고 보겠습니다. 발주처가 일정을 요구한다고 해서 바로 인원이나 작업시간부터 늘리지는 않겠습니다. 먼저 추가 뒤채움과 위험한 접근을 통제하고 배수·변위·균열 상태를 조사한다.\n\n그다음 원인을 확인하겠습니다. 균열 위치·방향·진행성, 뒤채움 순서·하중·배수, 기초 침하와 설계 가정을 비교한다. 이 자료를 현황 공정표와 연결해 해당 작업이 주공정인지, 여유가 있는지, 후속 작업을 다른 구간에서 진행할 수 있는지 확인하겠습니다. 작업 자체의 지연과 준공일 영향을 구분하고, 추가 투입비뿐 아니라 대기비와 현장 유지비도 같은 비교기간으로 산정하겠습니다.\n\n대안으로는 원인 제거 후 보수 / 구조 보강 / 부분 철거·재시공 등을 비교하겠습니다. 진행성 여부와 구조 영향을 먼저 진단하고 배수·하중 원인을 통제한다. 원인 제거 없이 균열만 덮지 않으며 성능 평가에 따라 보수·보강·재시공을 선택한다. 각 안의 단축 가능성과 비용은 협력업체의 실제 자원, 자재 확보, 검측과 승인기간까지 확인해 제시하겠습니다. 비용이 낮아도 안전과 품질을 충족하지 못하는 안은 선택하지 않겠습니다. 반대로 비용이 높은 안도 준공 위험을 실질적으로 줄이는지 근거를 확인하겠습니다.\n\n실행을 위해서는 설계사·구조 검토자·감리와 진단 범위를 정하고 주민에게 안전조치와 확인 결과를 설명한다. 저는 협의 때 확인된 사실, 아직 필요한 검토, 결정이 필요한 날짜를 구분해서 전달하겠습니다. 합의되지 않은 추가비나 공기 조정은 자동으로 인정받는다고 가정하지 않고, 계약상 절차와 객관적인 작업기록을 갖추겠습니다. 작업팀에는 변경된 순서와 책임, 중지·재개 조건을 분명히 공유하겠습니다.\n\n마지막으로 균열·변위·침하 추세, 배수 기능, 보강·보수 후 재발과 후속 재개 조건을 확인한다. 계획한 효과가 나오지 않거나 안전·품질 징후가 나빠지면 즉시 해당 작업을 통제하고 원인을 재분석하겠습니다. 실행 결과를 발주처와 공유하면서 대안을 조정하는 방식으로 관리하겠습니다.",
