    "interviewAnswer": "저라면 우선 이 상황의 핵심을 완료 비율보다 안전·기능·인수 조건의 잔여 경로를 관리해야 한다는 점이라고 보겠습니다. 발주처가 일정을 요구한다고 해서 바로 인원이나 작업시간부터 늘리지는 않겠습니다. 먼저 안전·기능 결함을 우선 분류하고 개방 제한·작업구역 분리 등 즉시 통제를 한다.\n\n그다음 원인을 확인하겠습니다. 항목별 위치·중요도·책임·원인·조달·재검사 소요기간과 문서 인수 조건을 확인한다. 이 자료를 현황 공정표와 연결해 해당 작업이 주공정인지, 여유가 있는지, 후속 작업을 다른 구간에서 진행할 수 있는지 확인하겠습니다. 작업 자체의 지연과 준공일 영향을 구분하고, 추가 투입비뿐 아니라 대기비와 현장 유지비도 같은 비교기간으로 산정하겠습니다.\n\n대안으로는 안전·기능 우선 보완 / 구역별 보완 전담조 / 서류·기관 검사 병행 등을 비교하겠습니다. 필수 안전·기능 결함을 최우선으로 폐쇄하고 구역별 전담조를 배치한다. 준공도면·시험·기관 검사는 병행하되 미완료를 서류만으로 완료 처리하지 않는다. 각 안의 단축 가능성과 비용은 협력업체의 실제 자원, 자재 확보, 검측과 승인기간까지 확인해 제시하겠습니다. 비용이 낮아도 안전과 품질을 충족하지 못하는 안은 선택하지 않겠습니다. 반대로 비용이 높은 안도 준공 위험을 실질적으로 줄이는지 근거를 확인하겠습니다.\n\n실행을 위해서는 감리·발주처·운영기관·협력업체와 인수 필수 항목, 확인 담당자·기한·재검사 일정을 합의한다. 저는 협의 때 확인된 사실, 아직 필요한 검토, 결정이 필요한 날짜를 구분해서 전달하겠습니다. 합의되지 않은 추가비나 공기 조정은 자동으로 인정받는다고 가정하지 않고, 계약상 절차와 객관적인 작업기록을 갖추겠습니다. 작업팀에는 변경된 순서와 책임, 중지·재개 조건을 분명히 공유하겠습니다.\n\n마지막으로 중요도별 미폐쇄 건수, 재발·재검사 불합격, 준공도면 일치율과 예상 인수일을 확인한다. 계획한 효과가 나오지 않거나 안전·품질 징후가 나빠지면 즉시 해당 작업을 통제하고 원인을 재분석하겠습니다. 실행 결과를 발주처와 공유하면서 대안을 조정하는 방식으로 관리하겠습니다.",
